class Solution:
    def onShelf(self, shelf: List[int], target: int) -> bool:
        a = shelf
        lo, hi = 0, len(a) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if a[mid] == target:
                return True
            if a[lo] == a[mid] == a[hi]:
                lo += 1
                hi -= 1
            elif a[lo] <= a[mid]:
                if a[lo] <= target < a[mid]:
                    hi = mid - 1
                else:
                    lo = mid + 1
            else:
                if a[mid] < target <= a[hi]:
                    lo = mid + 1
                else:
                    hi = mid - 1
        return False

